import './repl.css'

export type ReplResult = { ok: true; value: unknown } | { ok: false; error: string }
export interface ReplRunner {
  run(source: string, inputJSON: string): Promise<ReplResult>
  cancel(): void
  dispose(): void
}
export interface ReplOptions {
  runner: ReplRunner
  onClose(lastNumeric?: number): void
  onBusy?(busy: boolean): void
}

/** The supplied runner owns the bounded worker/VM; this UI never evaluates code. */
export function createRepl({ runner, onClose, onBusy }: ReplOptions) {
  const dialog = document.createElement('dialog')
  dialog.className = 'code-red-repl'
  dialog.setAttribute('aria-label', 'JavaScript scratchpad')
  dialog.innerHTML = `<div class="code-red-repl-heading"><h2>JavaScript scratchpad</h2><button type="button" data-repl-close>Close</button></div>
    <p>Each Run starts a fresh JavaScript environment. Variables do not carry over. This transcript lasts until you close the console.</p>
    <pre data-repl-input aria-label="Current input"></pre>
    <label>Code mode <select data-repl-mode><option value="expression">Expression</option><option value="statements">Statements with return</option></select></label>
    <label class="code-red-repl-editor">JavaScript<textarea data-repl-source rows="5" maxlength="8192" inputmode="text" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false"></textarea></label>
    <p class="code-red-repl-hint">Enter runs · Shift+Enter adds a line · Escape closes. Return an integer from 0 to 1530 to send a calculation back to the game on Close.</p>
    <div class="code-red-repl-actions"><button type="button" data-repl-run>Run</button><button type="button" data-repl-cancel disabled>Cancel run</button><span data-repl-status role="status"></span></div>
    <div data-repl-transcript role="log" aria-label="Calculation transcript" aria-live="polite"></div>`
  const source = dialog.querySelector<HTMLTextAreaElement>('[data-repl-source]')!
  const mode = dialog.querySelector<HTMLSelectElement>('[data-repl-mode]')!
  const runButton = dialog.querySelector<HTMLButtonElement>('[data-repl-run]')!
  const cancelButton = dialog.querySelector<HTMLButtonElement>('[data-repl-cancel]')!
  const transcript = dialog.querySelector<HTMLElement>('[data-repl-transcript]')!
  const status = dialog.querySelector<HTMLElement>('[data-repl-status]')!
  let generation = 0, submission = 0, busy = false, disposed = false
  let inputJSON = '', token: unknown, lastNumeric: number | undefined
  let previousFocus: HTMLElement | null = null
  document.body.appendChild(dialog)

  function setBusy(value: boolean) {
    if (busy !== value) { busy = value; onBusy?.(value) }
    runButton.disabled = value
    cancelButton.disabled = !value
    status.textContent = value ? 'Running…' : ''
  }
  function append(code: string, output: string) {
    const entry = document.createElement('div')
    const command = document.createElement('pre'), result = document.createElement('pre')
    command.textContent = `> ${code.slice(0, 8192)}`
    result.textContent = output
    entry.append(command, result)
    transcript.appendChild(entry)
    while (transcript.children.length > 20) transcript.firstElementChild!.remove()
    entry.scrollIntoView({ block: 'nearest' })
  }
  function cancel() {
    if (!busy) return
    submission++
    runner.cancel()
    setBusy(false)
    append('', 'Cancelled.')
  }
  async function run() {
    if (!dialog.open || busy || disposed) return
    const code = source.value.trim()
    if (!code) { status.textContent = 'Enter a calculation first.'; return }
    const body = mode.value === 'expression' ? `return (\n${code}\n);` : code
    const session = generation, request = ++submission, requestToken = token
    setBusy(true)
    try {
      const result = await runner.run(body, inputJSON)
      if (disposed || !dialog.open || session !== generation || request !== submission || requestToken !== token) return
      if (result.ok) {
        const formatted = JSON.stringify(result.value, null, 2)
        append(code, formatted === undefined ? 'No JSON result.' : formatted)
        if (typeof result.value === 'number' && Number.isInteger(result.value) && result.value >= 0 && result.value <= 1530) lastNumeric = result.value
      } else append(code, `Error: ${result.error}`)
    } catch {
      if (disposed || !dialog.open || session !== generation || request !== submission || requestToken !== token) return
      append(code, 'Error: calculation could not run.')
    } finally {
      if (session === generation && request === submission) setBusy(false)
    }
  }
  function close() {
    if (!dialog.open) return
    generation++; submission++
    runner.cancel()
    setBusy(false)
    const value = lastNumeric
    lastNumeric = undefined
    transcript.replaceChildren()
    dialog.close()
    previousFocus?.focus({ preventScroll: true })
    onClose(value)
  }
  dialog.addEventListener('keydown', event => {
    event.stopPropagation()
    if (event.isComposing) return
    if (event.key === 'Escape') { event.preventDefault(); close() }
    else if (event.key === 'Enter' && event.target === source && !event.shiftKey) { event.preventDefault(); if (!event.repeat) void run() }
  }, true)
  dialog.addEventListener('keyup', event => event.stopPropagation(), true)
  dialog.addEventListener('cancel', event => { event.preventDefault(); close() })
  runButton.onclick = () => { void run() }
  cancelButton.onclick = cancel
  dialog.querySelector<HTMLButtonElement>('[data-repl-close]')!.onclick = close
  return {
    open(stats: readonly number[], nextToken: unknown) {
      if (disposed) return
      generation++; submission++
      runner.cancel(); setBusy(false)
      token = nextToken; lastNumeric = undefined
      inputJSON = JSON.stringify({ stats: [...stats] })
      dialog.querySelector<HTMLElement>('[data-repl-input]')!.textContent = `input = ${inputJSON}`
      transcript.replaceChildren()
      source.value = 'input.stats.reduce((sum, n) => sum + n, 0)'
      mode.value = 'expression'
      if (!dialog.open) { previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null; dialog.showModal() }
      source.focus({ preventScroll: true })
    },
    close,
    dispose() {
      if (disposed) return
      disposed = true; generation++; submission++
      runner.cancel(); setBusy(false)
      if (dialog.open) dialog.close()
      dialog.remove(); runner.dispose()
    },
  }
}

import assert from 'node:assert/strict'
import { test } from 'node:test'
import { restoreRom } from './rom-cache.ts'
import { BASE_SHA1, MOD_SHA1, ROM_SIZE } from './patch.ts'
import { ROM_KEY, SOURCE_KEY, STATE_KEY } from './storage.ts'

const bytes = (tag: number) => { const result = new Uint8Array(ROM_SIZE); result[0] = tag; return result }
const digest = async (value: Uint8Array) => value[0] === 1 ? BASE_SHA1 : value[0] === 2 ? MOD_SHA1 : 'invalid'
function fixture(entries: [string, ArrayBuffer][] = []) {
  const files = new Map(entries)
  let patches = 0
  const cache = {
    read: async (key: string) => files.get(key),
    write: async (key: string, value: Uint8Array) => { files.set(key, value.slice().buffer) },
    patch: async (source: Uint8Array) => { assert.equal(source[0], 1); patches++; return bytes(2) },
  }
  return { files, cache, patches: () => patches }
}
test('reload reuses existing current patched cache without changing saves', async () => {
  const state = new ArrayBuffer(4)
  const f = fixture([[ROM_KEY, bytes(2).buffer], [STATE_KEY, state]])
  assert.equal((await restoreRom(f.cache, digest))?.bytes[0], 2)
  assert.equal(f.patches(), 0); assert.equal(f.files.get(STATE_KEY), state)
  assert.equal(f.files.has(SOURCE_KEY), false)
})
test('patch upgrade rebuilds from stable source, caches current build and leaves old ROM/state untouched', async () => {
  const old = bytes(3).buffer, state = new ArrayBuffer(4), source = bytes(1).buffer
  const f = fixture([[SOURCE_KEY, source], ['rom:old-build', old], ['state:old-build:old-core', state]])
  assert.equal((await restoreRom(f.cache, digest))?.remembered, true)
  assert.equal(f.patches(), 1); assert.equal(f.files.get(SOURCE_KEY), source)
  assert.equal(f.files.get('rom:old-build'), old); assert.equal(f.files.get('state:old-build:old-core'), state)
  await restoreRom(f.cache, digest); assert.equal(f.patches(), 1)
})
test('missing, evicted, wrong-sized and corrupt data prompt for source; corrupt current falls back to source', async () => {
  for (const entries of [[], [[SOURCE_KEY, new ArrayBuffer(1)]], [[SOURCE_KEY, bytes(3).buffer]], [['rom:old-build', bytes(2).buffer]]] as [string, ArrayBuffer][][]) {
    const f = fixture(entries); assert.equal(await restoreRom(f.cache, digest), undefined); assert.equal(f.patches(), 0)
  }
  const f = fixture([[ROM_KEY, bytes(3).buffer], [SOURCE_KEY, bytes(1).buffer]])
  assert.equal((await restoreRom(f.cache, digest))?.bytes[0], 2)
})
test('storage rejection allows choice; derived-cache write rejection still plays from retained source', async () => {
  const f = fixture([[SOURCE_KEY, bytes(1).buffer]])
  f.cache.write = async () => { throw new Error('quota') }
  assert.equal((await restoreRom(f.cache, digest))?.remembered, true)
  f.cache.read = async () => { throw new Error('blocked') }
  assert.equal(await restoreRom(f.cache, digest), undefined)
})
test('patch failures and invalid output preserve source for reload retry', async () => {
  const source = bytes(1).buffer, f = fixture([[SOURCE_KEY, source]])
  f.cache.patch = async () => { throw new Error('offline') }
  await assert.rejects(restoreRom(f.cache, digest), /offline/)
  f.cache.patch = async () => bytes(3)
  await assert.rejects(restoreRom(f.cache, digest), /verification/)
  assert.equal(f.files.get(SOURCE_KEY), source); assert.equal(f.files.has(ROM_KEY), false)
})

import { BASE_SHA1, MOD_SHA1, ROM_SIZE, sha1 } from './patch.ts'
import { ROM_KEY, SOURCE_KEY } from './storage.ts'

type Cache = {
  read(key: string): Promise<ArrayBuffer | undefined>
  write(key: string, bytes: Uint8Array): Promise<void>
  patch(source: Uint8Array): Promise<Uint8Array>
}

// Existing patched caches remain usable. Never mistake an old patched ROM for
// the original or migrate save states: only an independently verified source
// can produce a new build. Missing/corrupt/evicted entries fall back to choice.
export async function restoreRom(cache: Cache, digest = sha1) {
  async function verified(key: string, expected: string) {
    try {
      const stored = await cache.read(key)
      if (stored instanceof ArrayBuffer && stored.byteLength === ROM_SIZE) {
        const bytes = new Uint8Array(stored)
        if (await digest(bytes) === expected) return bytes
      }
    } catch { /* Storage can be unavailable independently of patch loading. */ }
  }
  const current = await verified(ROM_KEY, MOD_SHA1)
  if (current) return { bytes: current, remembered: true }
  const source = await verified(SOURCE_KEY, BASE_SHA1)
  if (!source) return undefined
  const bytes = await cache.patch(source)
  if (bytes.byteLength !== ROM_SIZE || await digest(bytes) !== MOD_SHA1) {
    throw new Error('Patch verification failed. Reload and try again.')
  }
  try { await cache.write(ROM_KEY, bytes) } catch { /* Source remains cached for the next reload. */ }
  return { bytes, remembered: true }
}

// Private to this browser/origin. No upload, account, or server-side save storage.
import { BASE_SHA1, MOD_SHA1 } from './patch.ts'

// Source identity is independent of the patched ROM and emulator/core versions.
export const SOURCE_KEY = `source:${BASE_SHA1}`
export const ROM_KEY = `rom:${MOD_SHA1}`
export const STATE_KEY = `state:${MOD_SHA1}:emulatorjs-4.2.3:mailbox-core-v2`

function open(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('code-red-local', 1)
    request.onupgradeneeded = () => request.result.createObjectStore('files')
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error)
    request.onblocked = () => reject(new Error('Browser storage is blocked.'))
  })
}

export async function readLocal(key: string): Promise<ArrayBuffer | undefined> {
  const database = await open()
  try {
    return await new Promise((resolve, reject) => {
      const transaction = database.transaction('files', 'readonly')
      const request = transaction.objectStore('files').get(key)
      transaction.oncomplete = () => resolve(request.result instanceof ArrayBuffer ? request.result : undefined)
      transaction.onabort = () => reject(transaction.error)
      transaction.onerror = () => reject(transaction.error)
    })
  } finally { database.close() }
}

export async function writeLocal(key: string, bytes: Uint8Array): Promise<void> {
  const database = await open()
  try {
    await new Promise<void>((resolve, reject) => {
      const transaction = database.transaction('files', 'readwrite')
      transaction.objectStore('files').put(new Uint8Array(bytes).buffer, key)
      transaction.oncomplete = () => resolve()
      transaction.onabort = () => reject(transaction.error)
      transaction.onerror = () => reject(transaction.error)
    })
  } finally { database.close() }
}

